const clientsState={items:[
{id:'1',name:'Clínica Aurora',email:'contato@clinicaexemplo.com.br',phone:'(47) 99999-0001',company:'Clínica Aurora',document:'',legalName:'',birth:'',cep:'',street:'',number:'',complement:'',district:'',city:'Itapema',state:'SC',project:'Marketing e conteúdo',pipeline:'Pipeline Principal',stage:'Em contato',start:'2026-06-20',months:'12',monthly:'1000',tags:['Performance Comercial'],archived:false,notes:'',contacts:[]},
{id:'2',name:'Grupo Horizonte',email:'contato@grupoexemplo.com.br',phone:'(48) 99999-0002',company:'Grupo Horizonte',document:'',legalName:'',birth:'',cep:'',street:'',number:'',complement:'',district:'',city:'Florianópolis',state:'SC',project:'Social Media',pipeline:'Pipeline Principal',stage:'Proposta',start:'2026-07-20',months:'12',monthly:'1200',tags:[],archived:false,notes:'',contacts:[]},
{id:'3',name:'Estúdio Mar',email:'contato@estudioexemplo.com.br',phone:'(47) 99999-0003',company:'Estúdio Mar',document:'',legalName:'',birth:'',cep:'',street:'',number:'',complement:'',district:'',city:'Balneário Camboriú',state:'SC',project:'Identidade visual',pipeline:'Pipeline Principal',stage:'Fechado',start:'2026-08-10',months:'6',monthly:'1500',tags:['Aguardando'],archived:false,notes:'',contacts:[]}
],search:'',showArchived:false,layout:'grid',modal:null,tab:'Informações'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const formatDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'—';
function renewal(c){if(!c.start||!Number(c.months))return null;const d=new Date(c.start+'T12:00:00');d.setMonth(d.getMonth()+Number(c.months));return d}
function toast(message){document.querySelector('.feedback')?.remove();const el=document.createElement('div');el.className='feedback';el.role='status';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3200)}
function renderClients(){document.querySelector('.workspace').classList.add('clients-mode');document.querySelector('#page-title').textContent='Clientes';document.querySelector('.workspace').innerHTML=`<div class="clients-shell"><div class="clients-head"><div><h2>Clientes</h2><p>Gerencie seus clientes cadastrados</p></div><div class="client-actions"><button type="button" class="c-btn ${clientsState.layout==='grid'?'active':''}" data-action="grid" aria-label="Visualizar em cartões">▦</button><button type="button" class="c-btn ${clientsState.layout==='list'?'active':''}" data-action="list" aria-label="Visualizar em lista">☷</button><button type="button" class="c-btn" data-action="tutorial">Tutorial</button><button type="button" class="c-btn" data-action="registration">Link de Cadastro</button><button type="button" class="c-btn" data-action="groups">Grupos</button><button type="button" class="c-btn primary" data-action="new">＋ Cadastrar Cliente</button></div></div><div class="client-filters"><label class="client-search"><span aria-hidden="true">⌕</span><input id="client-search" type="search" placeholder="Buscar por nome, email, empresa..." value="${esc(clientsState.search)}" aria-label="Buscar clientes"></label><label class="client-filter-check"><input id="show-archived" type="checkbox" ${clientsState.showArchived?'checked':''}> Mostrar arquivados</label></div><div class="stats" id="client-stats"></div><div class="client-grid ${clientsState.layout==='list'?'list':''}" id="client-list"></div></div>`;renderClientList();}
function renderClientList(){const now=new Date(),month=now.getMonth(),year=now.getFullYear();const active=clientsState.items.filter(c=>!c.archived);const newMonth=active.filter(c=>{const d=new Date(c.start);return d.getMonth()===month&&d.getFullYear()===year}).length;const renewing=active.filter(c=>{const d=renewal(c);return d&&d>=now&&d-now<=30*864e5}).length;document.querySelector('#client-stats').innerHTML=`<div class="stat">Total de Clientes<strong>${active.length}</strong></div><div class="stat">Novos este Mês<strong>${newMonth}</strong></div><div class="stat">Renovações próximas<strong>${renewing}</strong><small>nos próximos 30 dias</small></div>`;const q=clientsState.search.trim().toLocaleLowerCase('pt-BR');const result=clientsState.items.filter(c=>(clientsState.showArchived||!c.archived)&&[c.name,c.email,c.company,c.phone,c.project].some(s=>String(s||'').toLocaleLowerCase('pt-BR').includes(q)));document.querySelector('#client-list').innerHTML=result.length?result.map(c=>`<article class="client-card ${c.archived?'archived':''}" data-client-card="${c.id}" tabindex="0" aria-label="Abrir detalhes de ${esc(c.name)}"><div class="client-card-head"><div class="avatar" aria-hidden="true">${esc(c.name.slice(0,2).toUpperCase())}</div><div><h3>${esc(c.name)}</h3><span class="muted">${esc(c.project||'Sem projeto')}</span></div></div><p>✉ ${esc(c.email||'Sem e-mail')}</p><p>♧ ${esc(c.phone||'Sem telefone')}</p><p>▥ ${esc(c.company||'Sem empresa')}</p><div>${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="muted">Desde ${formatDate(c.start)}${renewal(c)?' · Renovação '+renewal(c).toLocaleDateString('pt-BR'):''}</p><hr><div><span class="muted">Valor mensal</span><div class="value">${money(c.monthly)}</div></div><div class="card-bottom"><button class="c-btn" data-action="details" data-id="${c.id}">Detalhes</button><button class="c-btn" data-action="edit" data-id="${c.id}">Editar</button><button class="c-btn" data-action="archive" data-id="${c.id}">${c.archived?'Restaurar':'Arquivar'}</button></div></article>`).join(''):'<div class="client-empty">Nenhum cliente encontrado. Ajuste a busca ou cadastre um cliente.</div>'}
function field(name,label,value='',type='text',extra=''){return `<label class="form-field ${extra}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='name'?'required':''}></label>`}
function select(name,label,value,options){return `<label class="form-field">${label}<select name="${name}">${options.map(o=>`<option value="${esc(o)}" ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function section(title,content){return `<section class="form-section"><h3>${title}</h3>${content}</section>`}
function contactRows(c){const rows=Array.isArray(c?.contacts)?c.contacts:[];return `<div class="contacts-heading"><div><h3>Contatos</h3><p>Pessoas de contato ligadas a este cliente.</p></div><button type="button" class="c-btn primary" data-action="new-contact" ${c?'':'disabled'}>＋ Adicionar</button></div>${rows.length?`<div class="contact-list">${rows.map(x=>`<div class="contact-row"><div class="contact-avatar">${esc((x.name||'?').slice(0,2).toUpperCase())}</div><div class="contact-info"><strong>${esc(x.name)}</strong>${x.primary?'<span class="contact-primary">Principal</span>':''}<small>${esc(x.role||'Contato')}${x.phone?' · '+esc(x.phone):''}${x.email?' · '+esc(x.email):''}</small>${x.notes?`<small>${esc(x.notes)}</small>`:''}${x.notify?'<small>Notificações por WhatsApp ativadas</small>':''}</div><div class="contact-actions"><button type="button" class="c-btn" data-action="edit-contact" data-id="${esc(x.id)}">Editar</button><button type="button" class="c-btn" data-action="delete-contact" data-id="${esc(x.id)}">Remover</button></div></div>`).join('')}</div>`:'<div class="contacts-empty"><span aria-hidden="true">♙</span><p>Nenhum contato cadastrado ainda.</p></div>'}`}
function renderModal(){let modal=clientsState.modal;if(!modal)return;document.querySelector('.modal-back')?.remove();let c=modal.id?clientsState.items.find(x=>x.id===modal.id):null;const title=modal.kind==='new'?'Cadastrar Cliente':modal.kind==='registration'?'Link de Cadastro':modal.kind==='groups'?'Grupos':modal.kind==='tutorial'?'Como usar Clientes':modal.kind==='technical'?'Ficha Técnica':'Detalhes do Cliente';let body='';if(['new','details','edit','technical'].includes(modal.kind)){const tabs=['Informações','Contatos','Projetos','Arquivos','Pendências','Serviços','Financeiro'];const tab=modal.kind==='new'?'Informações':clientsState.tab;const visibleTags=c?.tags||modal.tags||[];body=`${modal.kind!=='new'?`<div class="modal-tabs" role="tablist" aria-label="Seções do cliente">${tabs.map(t=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-action="tab" data-tab="${t}">${t}</button>`).join('')}</div><div class="detail-summary"><div class="avatar">${esc((c?.name||'CL').slice(0,2).toUpperCase())}</div><div><strong>${esc(c?.name)}</strong><div class="muted">${esc(c?.company||'')}</div></div></div>`:''}<form id="client-form"><div class="tab-panel" ${tab==='Informações'?'':'hidden'}>${section('Contato',`<div class="form-grid">${field('name','Nome do Cliente',c?.name)}${field('email','E-mail',c?.email,'email')}${field('phone','Telefone',c?.phone,'tel')}${field('whatsappGroup','Grupo de WhatsApp vinculado',c?.whatsappGroup)}</div>`)}${section('Dados e documentos',`<div class="form-grid">${field('company','Nome fantasia',c?.company,'text','full')}${field('document','CPF/CNPJ',c?.document)}${field('birth','Data de nascimento',c?.birth,'date')}${field('legalName','Razão Social',c?.legalName,'text','full')}</div>`)}${section('Endereço',`<div class="form-grid three">${field('cep','CEP',c?.cep)}${field('street','Rua / Avenida',c?.street)}${field('number','Número',c?.number)}${field('complement','Complemento',c?.complement)}${field('district','Bairro',c?.district)}${field('city','Cidade',c?.city)}${field('state','Estado',c?.state)}</div>`)}${section('Tags',`<div class="tag-editor" id="tag-editor">${visibleTags.map(t=>`<span class="tag">${esc(t)} <button type="button" data-action="remove-tag" data-tag="${esc(t)}" aria-label="Remover ${esc(t)}">×</button></span>`).join('')}</div><div class="form-grid"><label class="form-field">Adicionar tag<input id="tag-input" placeholder="Digite uma tag e pressione Enter"></label><button type="button" class="c-btn" data-action="add-tag" style="align-self:end">Adicionar</button></div>`)}${section('Projeto e pipeline',`<div class="form-grid">${field('project','Projeto',c?.project,'text','full')}${field('pipeline','Pipeline',c?.pipeline)}${select('stage','Etapa do Pipeline',c?.stage||'Em contato',['Em contato','Proposta','Negociação','Fechado','Pausado'])}</div>`)}${section('Gestão de contrato',`<div class="form-grid three">${field('start','Cliente desde',c?.start,'date')}${field('months','Meses contratados',c?.months,'number')}${field('monthly','Valor mensal (R$)',c?.monthly,'number')}</div>`)}${section('Observações',`<label class="form-field">Anotações<textarea name="notes">${esc(c?.notes)}</textarea></label>`)}</div><div class="tab-panel" ${tab==='Contatos'?'':'hidden'}>${contactRows(c)}</div>${tabs.slice(2).map(t=>`<div class="tab-panel" ${tab===t?'':'hidden'}>${t==='Projetos'?projectPanel(c):section(t,`<p class="small-note">Ainda não há ${t.toLocaleLowerCase('pt-BR')} vinculados a este cliente.</p>`)}</div>`).join('')}</form>`}else if(modal.kind==='registration'){body='<p class="small-note">O cadastro externo de clientes requer uma página pública e validação de acesso. Esta etapa será conectada quando o módulo de cadastro estiver pronto.</p>'}else if(modal.kind==='groups'){body='<p class="small-note">Os grupos de WhatsApp vinculados serão sincronizados após a integração de Atendimento.</p>'}else{body='<p class="small-note">Cadastre um cliente, use a busca para localizar seus dados e abra Detalhes para atualizar contrato, endereço, tags e contatos.</p>'}const root=document.createElement('div');root.className='modal-back';root.innerHTML=`<div class="client-modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><div style="display:flex;gap:8px">${c&&modal.kind!=='technical'?`<button class="c-btn" data-action="technical" data-id="${c.id}">Ficha Técnica</button>`:''}<button class="c-btn" data-action="close" aria-label="Fechar">×</button></div></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="c-btn" data-action="close">Fechar</button>${['new','edit','details','technical'].includes(modal.kind)?'<button class="c-btn primary" type="submit" form="client-form">Salvar cliente</button>':''}</div></div>`;document.body.append(root);root.querySelector('input[name="name"]')?.focus()}
function openModal(kind,id){clientsState.tab='Informações';clientsState.modal={kind,id};renderModal()}
function closeModal(){clientsState.modal=null;document.querySelector('.modal-back')?.remove()}
function saveClient(form){const values=Object.fromEntries(new FormData(form));const existing=clientsState.modal.id?clientsState.items.find(c=>c.id===clientsState.modal.id):null;const name=(values.name||existing?.name||'').trim();if(!name){toast('Informe o nome do cliente.');return}const c=existing||{id:String(Date.now()),tags:[...(clientsState.modal.tags||[])],archived:false,contacts:[]};Object.assign(c,values,{name,monthly:Math.max(0,Number(values.monthly??c.monthly)||0),contacts:c.contacts});if(!existing)clientsState.items.unshift(c);closeModal();renderClients();toast(existing?'Cliente atualizado nesta visualização.':'Cliente cadastrado nesta visualização.')}
document.addEventListener('input',e=>{if(e.target.id==='client-search'){clientsState.search=e.target.value;renderClientList()}});document.addEventListener('change',e=>{if(e.target.id==='show-archived'){clientsState.showArchived=e.target.checked;renderClientList()}});document.addEventListener('submit',e=>{if(e.target.id==='contact-form'){e.preventDefault();saveContact(e.target);return}if(e.target.id==='client-form'){e.preventDefault();saveClient(e.target)}});document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){const card=e.target.closest('[data-client-card]');if(card)openModal('details',card.dataset.clientCard);return}const a=b.dataset.action,id=b.dataset.id;if(a==='grid'||a==='list'){clientsState.layout=a;renderClients()}else if(['new','details','edit','technical','registration','groups','tutorial'].includes(a))openModal(a,id);else if(a==='close')closeModal();else if(a==='new-contact')openContact();else if(a==='edit-contact')openContact(id);else if(a==='delete-contact'){const c=clientsState.items.find(x=>x.id===clientsState.modal?.id);if(c&&confirm('Remover este contato?')){c.contacts=c.contacts.filter(x=>x.id!==id);refreshContacts();toast('Contato removido nesta visualização.')}}else if(a==='archive'){const c=clientsState.items.find(c=>c.id===id);c.archived=!c.archived;renderClientList();toast(c.archived?'Cliente arquivado nesta visualização.':'Cliente restaurado.')}else if(a==='tab'){clientsState.tab=b.dataset.tab;document.querySelectorAll('.modal-tabs button').forEach(x=>{x.classList.toggle('active',x.dataset.tab===clientsState.tab);x.setAttribute('aria-selected',String(x.dataset.tab===clientsState.tab))});document.querySelectorAll('.tab-panel').forEach((x,i)=>x.hidden=['Informações','Contatos','Projetos','Arquivos','Pendências','Serviços','Financeiro'][i]!==clientsState.tab)}else if(a==='add-tag'){const input=document.querySelector('#tag-input'),v=input.value.trim();if(!v)return;const c=clientsState.items.find(c=>c.id===clientsState.modal.id);const tags=c?c.tags:clientsState.modal.tags||(clientsState.modal.tags=[]);if(!tags.includes(v)){tags.push(v);const editor=document.querySelector('#tag-editor');const chip=document.createElement('span');chip.className='tag';chip.textContent=v+' ';const remove=document.createElement('button');remove.type='button';remove.dataset.action='remove-tag';remove.dataset.tag=v;remove.setAttribute('aria-label','Remover '+v);remove.textContent='×';chip.append(remove);editor.append(chip)}input.value=''}else if(a==='remove-tag'){const c=clientsState.items.find(c=>c.id===clientsState.modal.id);if(c)c.tags=c.tags.filter(t=>t!==b.dataset.tag);else clientsState.modal.tags=(clientsState.modal.tags||[]).filter(t=>t!==b.dataset.tag);b.closest('.tag').remove()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('.contact-dialog'))closeContact();else closeModal()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-client-card]')){e.preventDefault();openModal('details',e.target.dataset.clientCard)}if(e.key==='Enter'&&e.target.id==='tag-input'){e.preventDefault();document.querySelector('[data-action="add-tag"]')?.click()}});document.addEventListener('click',e=>{if(e.target.classList.contains('modal-back'))closeModal()});

function refreshContacts(){const panel=document.querySelectorAll('.client-modal .tab-panel')[1],c=clientsState.items.find(x=>x.id===clientsState.modal?.id);if(panel)panel.innerHTML=contactRows(c)}
function openContact(id){const client=clientsState.items.find(x=>x.id===clientsState.modal?.id);if(!client){toast('Salve o cliente antes de adicionar contatos.');return}const contact=client.contacts.find(x=>x.id===id);document.querySelector('.contact-dialog')?.remove();const layer=document.createElement('div');layer.className='contact-dialog';layer.innerHTML=`<div class="contact-dialog-card" role="dialog" aria-modal="true" aria-label="${contact?'Editar contato':'Novo contato'}"><div class="contact-dialog-head"><h2>${contact?'Editar contato':'Novo contato'}</h2><button type="button" data-action="close-contact" aria-label="Fechar">×</button></div><form id="contact-form"><label>Nome<input name="name" placeholder="Nome do contato" value="${esc(contact?.name)}" required autofocus></label><label>Cargo<input name="role" placeholder="Ex: Financeiro, Sócio, Comprador" value="${esc(contact?.role)}"></label><div class="contact-two"><label>Telefone<input name="phone" type="tel" placeholder="(00) 00000-0000" value="${esc(contact?.phone)}"></label><label>E-mail<input name="email" type="email" placeholder="email@exemplo.com" value="${esc(contact?.email)}"></label></div><label>Observações<textarea name="notes" rows="3">${esc(contact?.notes)}</textarea></label><label class="contact-check"><input type="checkbox" name="primary" ${contact?.primary?'checked':''}> Marcar como contato principal</label><label class="contact-check contact-notify"><input type="checkbox" name="notify" ${contact?.notify?'checked':''}><span><strong>Notificações por WhatsApp</strong><small>Enviar notificações automáticas para este contato via WhatsApp.</small></span></label><div class="contact-dialog-foot"><button type="button" class="c-btn" data-action="close-contact">Cancelar</button><button class="c-btn primary" type="submit">${contact?'Salvar':'Adicionar'}</button></div></form></div>`;layer.dataset.contactId=id||'';document.body.append(layer);layer.querySelector('[name="name"]').focus()}
function closeContact(){document.querySelector('.contact-dialog')?.remove()}
function saveContact(form){const client=clientsState.items.find(x=>x.id===clientsState.modal?.id),layer=document.querySelector('.contact-dialog');if(!client||!layer)return;const f=Object.fromEntries(new FormData(form)),name=(f.name||'').trim();if(!name){toast('Informe o nome do contato.');return}const existing=client.contacts.find(x=>x.id===layer.dataset.contactId);const data={id:existing?.id||String(Date.now()),name,role:(f.role||'').trim(),phone:(f.phone||'').trim(),email:(f.email||'').trim(),notes:(f.notes||'').trim(),primary:!!f.primary,notify:!!f.notify};if(data.primary)client.contacts.forEach(x=>x.primary=false);if(existing)Object.assign(existing,data);else client.contacts.push(data);closeContact();refreshContacts();toast('Contato salvo nesta visualização.')}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="close-contact"]'))closeContact();else if(e.target.classList.contains('contact-dialog'))closeContact()});
